"""Cart pricing."""

from cart.models import Line, Totals


def price_cart(lines: list[Line], coupon: str | None = None) -> Totals:
    """Price a cart. See README.md for the discount rules."""
    # Validate inputs
    for line in lines:
        if line.qty < 1:
            raise ValueError("Quantity must be at least 1")
        if line.unit_cents < 0:
            raise ValueError("Unit price cannot be negative")

    # Calculate subtotal
    subtotal = sum(line.unit_cents * line.qty for line in lines)

    # Calculate bulk discount (10% off for lines with qty >= 10)
    bulk_discount = 0
    for line in lines:
        if line.qty >= 10:
            line_amount = line.unit_cents * line.qty
            # Calculate 10% discount, rounding halves up
            discount = (line_amount * 10 + 99) // 100  # This rounds halves up
            bulk_discount += discount

    # Apply bulk discount to get amount eligible for coupon
    amount_after_bulk = subtotal - bulk_discount

    # Apply coupon if provided
    coupon_discount = 0
    if coupon is not None:
        if coupon.startswith("PERCENT:"):
            try:
                percent = int(coupon[8:])
                if not 1 <= percent <= 100:
                    raise ValueError("Percentage must be between 1 and 100")
                # Calculate percentage discount, rounding halves up
                coupon_discount = (amount_after_bulk * percent + 99) // 100
            except ValueError:
                raise ValueError("Invalid PERCENT coupon format")
        elif coupon.startswith("FIXED:"):
            try:
                fixed_amount = int(coupon[6:])
                if fixed_amount < 0:
                    raise ValueError("Fixed amount cannot be negative")
                coupon_discount = min(fixed_amount, amount_after_bulk)
            except ValueError:
                raise ValueError("Invalid FIXED coupon format")
        else:
            raise ValueError("Coupon must be either PERCENT:n or FIXED:n")

    # Total discount is bulk discount plus coupon discount
    total_discount = bulk_discount + coupon_discount

    # Final total is subtotal minus total discount
    total = subtotal - total_discount

    return Totals(subtotal=subtotal, discount=total_discount, total=total)
